const FACTS_DATA={0:{owner:"Kamil Krzyżanowski (prezes) · Sebastian Hejnowski",owner_en:"Kamil Krzyżanowski (president) · Sebastian Hejnowski",chain:"Wspólnicy os. fiz. (PL), 500 000 zł / 300 000 zł udziałów",chain_en:"Individual shareholders (PL), PLN 500,000 / PLN 300,000 in shares",benef:"Polska",benef_en:"Poland",note:"Beneficjent Monika Ziółek (członek zarządu) zasiada równocześnie w komisji rewizyjnej PSWK (organie nadzoru stowarzyszenia), które lobbuje ws. ustawy UC135. Renters złożył też formalne stanowisko w konsultacjach publicznych projektu (30.04.2026).",note_en:"Board member Monika Ziółek also sits on PSWK's audit committee (the association's oversight body), which lobbies on the UC135 bill. Renters also submitted a formal position during the bill's public consultations (30.04.2026).",sources:'<a href="https://www.rp.pl/nieruchomosci/art43218081-wystarcza-proste-rozwiazania-by-uregulowac-najem-krotkoterminowy-mieszkan" target="_blank" rel="noopener">rp.pl</a> · <a href="https://renters.pl/stanowisko-renters-w-sprawie-projektu-ustawy/" target="_blank" rel="noopener">renters.pl, stanowisko</a> · <a href="https://rejestr.io/krs/793271/polskie-stowarzyszenie-wynajmu-krotkoterminowego" target="_blank" rel="noopener">rejestr.io, PSWK, komisja rewizyjna</a> · <a href="https://pswk.pl/o-nas/" target="_blank" rel="noopener">pswk.pl</a> · <a href="https://rejestr.io/krs/678215/renters" target="_blank" rel="noopener">rejestr.io</a> · <a href="https://www.airbnb.com/rooms/1660048255979107572" target="_blank" rel="noopener">airbnb.com</a>'},
1:{owner:"Andrzej Stecki (założyciel, prezes)",owner_en:"Andrzej Stecki (founder, president)",chain:"Osoba fizyczna (PL) · rodzina z podwójnym obywatelstwem PL/USA/Brazylia",chain_en:"Private individual (PL) · family holding dual PL/US/Brazil citizenship",benef:"Polska",benef_en:"Poland",note:"Ten sam telefon (+48 798 148 •••) i adres (Nakielska 3) łączą wszystkie 3 formaty numeru rejestracyjnego w jeden podmiot (patrz krok 05).",note_en:"The same phone number (+48 798 148 •••) and address (Nakielska 3) link all 3 formats of the registration number to a single entity (see the identity step above).",sources:'<a href="https://www.rp.pl/nieruchomosci/art41413341-najem-krotkoterminowy-promil-rynku-do-uporzadkowania" target="_blank" rel="noopener">rp.pl</a> · <a href="https://rejestr.io/osoby/655932/andrzej-stecki" target="_blank" rel="noopener">rejestr.io</a> · <a href="https://www.airbnb.com/rooms/1665917191629020772" target="_blank" rel="noopener">airbnb.com</a>'},
8:{owner:"PANDO APARTMENTS S.L. (Hiszpania)",owner_en:"PANDO APARTMENTS S.L. (Spain)",chain:"Spółka-matka · Málaga + założyciele osobiście",chain_en:"Parent company · Málaga + founders personally",benef:"Hiszpania",benef_en:"Spain",note:"Prezes PL: Olaf Dzierżykray-Rogalski. Polski operator z hiszpańskim kapitałem założycielskim.",note_en:"PL president: Olaf Dzierżykray-Rogalski. A Polish operator with Spanish founding capital.",sources:'rejestr.io, KRS 0000675309 · pandoapartments.com · CRBR · <a href="https://www.airbnb.com/rooms/53712991" target="_blank" rel="noopener">airbnb.com</a>'},
12:{owner:"Aliaksei Piankrat (prezes, 65% udziałów) · Roman Popovych (członek zarządu, 35% udziałów)",owner_en:"Aliaksei Piankrat (president, 65% of shares) · Roman Popovych (board member, 35% of shares)",chain:"Apartstate Sp. z o.o., siedziba: Łódź, zarządza ofertami w Warszawie zdalnie",chain_en:"Apartstate Sp. z o.o., registered in Łódź, manages Warsaw listings remotely",benef:"Nieustalone",benef_en:"Not established",note:"Telefon +48 531 636 ••• spina dwa różne numery rejestracyjne w jeden podmiot z odległego miasta. Na Airbnb hosta reprezentują rotacyjnie różne imiona (Roman, Alex, Dmitry, Hanna), żadne nie wskazuje na spółkę ani jej wspólników.",note_en:"Phone number +48 531 636 ••• ties two different registration numbers to a single entity based in a distant city. On Airbnb, the host is represented on a rotating basis by different first names (Roman, Alex, Dmitry, Hanna), none of which point to the company or its shareholders.",sources:'rejestr.io, KRS 0000787196 · dane własne zbioru (business_details, warsaw_listings_enriched.json)'},
9:{owner:"Adrian Niżnik Barwicki (prezes zarządu, beneficjent) · Liya Akhramovich (zarząd, wspólniczka) · Ilkimen Consulting GmbH (Niemcy, wspólnik)",owner_en:"Adrian Niżnik Barwicki (board president, beneficiary) · Liya Akhramovich (board, shareholder) · Ilkimen Consulting GmbH (Germany, shareholder)",chain:"Rentujemy Sp. z o.o. (PL) · trzeci wspólnik: Vester Fundacja Rodzinna · druga beneficjentka: Teresa Barwicka",chain_en:"Rentujemy Sp. z o.o. (PL) · third shareholder: Vester Fundacja Rodzinna · second beneficiary: Teresa Barwicka",benef:"Niemcy (wspólnik) · Zjednoczone Emiraty Arabskie (rezydencja prezesa)",benef_en:"Germany (shareholder) · United Arab Emirates (president's residency)",note:"Adrian Niżnik Barwicki, prezes zarządu i potwierdzony beneficjent rzeczywisty spółki, jest w CRBR wpisany jako rezydent Zjednoczonych Emiratów Arabskich. Ilkimen Consulting GmbH to realna niemiecka spółka z Walldorfu (HRB 753409, Sąd Rejonowy w Mannheim), założona w styczniu 2025 przez Sefę Bayrama Ilkimena, rzadki w tym zbiorze przypadek kapitału zagranicznego idącego przez małą spółkę konsultingową, nie duży fundusz.",note_en:"Adrian Niżnik Barwicki, the company's board president and a confirmed beneficial owner, is listed in the CRBR as a resident of the United Arab Emirates. Ilkimen Consulting GmbH is a real German company based in Walldorf (HRB 753409, Mannheim District Court), founded in January 2025 by Sefa Bayram Ilkimen, a rare case in this dataset of foreign capital flowing through a small consulting company rather than a large fund.",sources:'rejestr.io, KRS 0001003921 · CRBR · <a href="https://www.online-handelsregister.de/handelsregisterauszug/bw/Mannheim/HRB/753409/Ilkimen-Consulting-GmbH" target="_blank" rel="noopener">online-handelsregister.de</a> · <a href="https://www.airbnb.com/rooms/1634048227941510519" target="_blank" rel="noopener">airbnb.com</a>'},
3:{owner:"Paulina Benda (prezeska)",owner_en:"Paulina Benda (president)",chain:"Spółka z o.o. (PL)",chain_en:"Limited-liability company (PL)",benef:"Polska",benef_en:"Poland",note:"Cytowana w tym samym artykule rp.pl co BookingHost: „Nie zgadzam się z tezą, że najem krótkoterminowy jest głównym czynnikiem wzrostu czynszów”.",note_en:"Quoted in the same rp.pl article as BookingHost: \"I don't agree with the claim that short-term rental is the main driver of rising rents.\"",sources:'<a href="https://www.rp.pl/nieruchomosci/art41413341-najem-krotkoterminowy-promil-rynku-do-uporzadkowania" target="_blank" rel="noopener">rp.pl</a> · <a href="https://www.airbnb.com/rooms/1721845712589769149" target="_blank" rel="noopener">airbnb.com</a>'},
7:{owner:"Ewa Wielgórska (prezeska)",owner_en:"Ewa Wielgórska (president)",chain:"Spółka z o.o. (PL)",chain_en:"Limited-liability company (PL)",benef:"Polska",benef_en:"Poland",note:"W prasie o projekcie ustawy mówiła wprost: „Obowiązek meldunkowy w połączeniu z prawem do odmowy przyjęcia rezerwacji to proste rozwiązania”.",note_en:"Speaking to the press about the draft bill, she said directly: \"A registration requirement combined with the right to decline a booking are simple solutions.\"",sources:'<a href="https://www.rp.pl/nieruchomosci/art43575201-najem-krotkoterminowy-maja-patent-na-uciazliwych-gosci-ale-rzad-ich-nie-slucha" target="_blank" rel="noopener">rp.pl</a> · <a href="https://www.propertynews.pl/mieszkania/wazne-zmiany-w-przepisach-o-najmie-operatorzy-dopieli-swego,196283.html" target="_blank" rel="noopener">propertynews.pl</a> · <a href="https://fairyflats.com/2026/02/01/najem-krotkoterminowy-regulacje-ustawa/" target="_blank" rel="noopener">fairyflats.com</a> · <a href="https://www.airbnb.com/rooms/1734020578650049779" target="_blank" rel="noopener">airbnb.com</a>'},
13:{owner:"Grażyna Piotrowska-Oliwa (przewodnicząca rady nadzorczej)",owner_en:"Grażyna Piotrowska-Oliwa (chair of the supervisory board)",chain:"Inwestorka, była prezes PGNiG i Orange Polska, dziś w zarządzie Pepco Group",chain_en:"Investor, former president of PGNiG and Orange Polska, currently on the board of Pepco Group",benef:"Polska",benef_en:"Poland",note:"Najbardziej rozpoznawalne nazwisko w całym zbiorze, potwierdzone niezależnie w CRBR.",note_en:"The most recognizable name in the entire dataset, independently confirmed in the CRBR.",sources:'<a href="https://rejestr.io/krs/658841/rentplanet-apartments" target="_blank" rel="noopener">rejestr.io</a> · CRBR · biogram własny (Forbes Polska) · <a href="https://www.airbnb.com/rooms/1203396022150281679" target="_blank" rel="noopener">airbnb.com</a>'},
18:{owner:"Maciej Jan Gliński (prezes)",owner_en:"Maciej Jan Gliński (president)",chain:"Ten sam prezes i adres (Grzybowska 43a) co Golden Apartments WKZ i Golden Villas, obie zarejestrowane tego samego dnia, 12.10.2023",chain_en:"The same president and address (Grzybowska 43a) as Golden Apartments WKZ and Golden Villas, both registered on the same day, 12.10.2023",benef:"Polska",benef_en:"Poland",note:"Razem trzy spółki tego samego właściciela odpowiadają za ok. 90 ofert w zbiorze, nie 66, osobno wyglądają jak niezależni, mali operatorzy.",note_en:"Together, the three companies under the same owner account for around 90 listings in the dataset, not 66, viewed separately, they look like independent, small operators.",sources:'<a href="https://rejestr.io/krs/947610/golden-apartments-glamping" target="_blank" rel="noopener">rejestr.io, & Glamping</a> · <a href="https://rejestr.io/krs/1063380/golden-apartments-wkz" target="_blank" rel="noopener">rejestr.io, WKZ</a> · <a href="https://rejestr.io/krs/1063447/golden-villas" target="_blank" rel="noopener">rejestr.io, Villas</a> · <a href="https://www.airbnb.com/rooms/1157098342209598540" target="_blank" rel="noopener">airbnb.com</a>'},
2:{owner:"Danuta Wiesława Rakowska (prezes zarządu, od 2024) · Damian Lachowicz (wspólnik od 2017)",owner_en:"Danuta Wiesława Rakowska (board president, since 2024) · Damian Lachowicz (shareholder since 2017)",chain:"Sp. z o.o. (PL), trzej kolejni prezesi: Sławomir Ambruszkiewicz → Krystian Babiel → Danuta Rakowska",chain_en:"Limited-liability company (PL), three successive presidents: Sławomir Ambruszkiewicz → Krystian Babiel → Danuta Rakowska",benef:"Polska",benef_en:"Poland",note:"Trzy nazwiska w rejestrze beneficjentów odpowiadają kolejnym po sobie prezesom spółki, nie trzem równoległym właścicielom. Ambruszkiewicz jest jednocześnie powiązany z siedmioma innymi spółkami i fundacjami (m.in. IMPRESIO, GODZILLA, Instytut Analiz Prawnych); Babiel pojawia się też jako beneficjent w Potwory I, w obu przypadkach to wzorzec seryjnego udziałowca drobnych spółek, bez dalszych ustaleń w prasie.",note_en:"The three names in the beneficial-owner register correspond to successive company presidents, not three simultaneous owners. Ambruszkiewicz is simultaneously tied to seven other companies and foundations (including IMPRESIO, GODZILLA, Instytut Analiz Prawnych); Babiel also appears as a beneficiary of Potwory I, in both cases a pattern of a serial small-company office-holder, with no further findings in the press.",sources:'rejestr.io, KRS 0000692710 · <a href="https://rejestr.io/osoby/339128/slawomir-ambruszkiewicz" target="_blank" rel="noopener">rejestr.io, Ambruszkiewicz</a>'},
4:{owner:"Szymon Piotr Hahn (prezes)",owner_en:"Szymon Piotr Hahn (president)",chain:"Spółka z o.o. (PL)",chain_en:"Limited-liability company (PL)",benef:"Polska",benef_en:"Poland",note:"Standardowy profil korporacyjny, prezes aktywny publicznie pod własnym nazwiskiem. Sprawdzone pod kątem prasy i powiązań, bez dodatkowych ustaleń poza samym wpisem do rejestru.",note_en:"A standard corporate profile, with the president publicly active under his own name. Checked against press coverage and connections, no findings beyond the registry entry itself.",sources:'rejestr.io, KRS 0000601230 · <a href="https://hosthelper.pl/o-nas/" target="_blank" rel="noopener">hosthelper.pl</a>'},
5:{owner:"Tomasz Juliusz Marciniak (prezes) · Małgorzata Irmina Zielińska-Marciniak (wspólniczka)",owner_en:"Tomasz Juliusz Marciniak (president) · Małgorzata Irmina Zielińska-Marciniak (shareholder)",chain:"Spółka z o.o. (PL), założona styczeń 2022",chain_en:"Limited-liability company (PL), founded January 2022",benef:"Polska",benef_en:"Poland",note:"Wspólny człon nazwiska wspólników wskazuje na rodzinny charakter spółki, ten sam wzorzec co przy kilku innych mniejszych operatorach w tym zbiorze. Bez dalszych ustaleń w prasie.",note_en:"The shared surname between the two shareholders points to a family-run company, the same pattern seen at several other smaller operators in this dataset. No further findings in the press.",sources:'rejestr.io, KRS 0000947238 · <a href="https://www.emis.com/php/company-profile/PL/Essa_Development_Sp_z_oo_pl_13329576.html" target="_blank" rel="noopener">emis.com</a>'},
6:{owner:"Krystian Kowalik (prezes, od 2011)",owner_en:"Krystian Kowalik (president, since 2011)",chain:"Wspólnicy: Capital Bridge Investments Sp. z o.o. (ten sam adres co Homeprime) · WK Kowalik Sp. z o.o. (własna spółka-wehikuł Kowalika)",chain_en:"Shareholders: Capital Bridge Investments Sp. z o.o. (registered at the same address as Homeprime) · WK Kowalik Sp. z o.o. (Kowalik's own personal holding vehicle)",benef:"Polska",benef_en:"Poland",note:"Oba podmioty-wspólnicy noszą znamiona wewnętrznych wehikułów tej samej osoby, nie kapitału zewnętrznego: Capital Bridge Investments jest zarejestrowany pod tym samym adresem co sama spółka, a WK Kowalik nosi inicjały prezesa.",note_en:"Both shareholder entities look like internal vehicles of the same person rather than outside capital: Capital Bridge Investments is registered at the same address as the company itself, and WK Kowalik carries the president's own initials.",sources:'<a href="https://rejestr.io/krs/381373/homeprime" target="_blank" rel="noopener">rejestr.io</a> · <a href="https://rejestr.io/krs/844956/capital-bridge-investments" target="_blank" rel="noopener">rejestr.io, Capital Bridge Investments</a>'},
10:{owner:"Maciej Kozłowski (jednoosobowa działalność gospodarcza)",owner_en:"Maciej Kozłowski (sole proprietorship)",chain:"JDG (NIP PL 5262162120), brak osobnego rejestru beneficjentów dla działalności jednoosobowej",chain_en:"Sole proprietorship (NIP PL 5262162120), sole proprietorships have no separate beneficial-owner register to check",benef:"Polska",benef_en:"Poland",note:"Operator jest jednocześnie jedynym właścicielem, w odróżnieniu od spółek nie ma tu oddzielnej warstwy CRBR do sprawdzenia.",note_en:"The operator is simultaneously the sole owner. Unlike companies, there's no separate CRBR layer to check here. ",sources:'dane własne zbioru (business_details, warsaw_listings_enriched.json)'},
11:{owner:"Aleksander Maksymilian Pisarek (założyciel, prezes od 2022) · Bartosz Szewczak i Maciej Wasilewski (zarząd i wspólnicy od czerwca 2024)",owner_en:"Aleksander Maksymilian Pisarek (founder, president since 2022) · Bartosz Szewczak and Maciej Wasilewski (board and shareholders since June 2024)",chain:"Sp. z o.o. (PL), rozszerzona z jednoosobowego założyciela do trzyosobowego zarządu",chain_en:"Limited-liability company (PL), expanded from a single founder to a three-person board",benef:"Polska",benef_en:"Poland",note:"Pisarek założył spółkę samodzielnie w marcu 2022 jako jedyny wspólnik i beneficjent; dwóch kolejnych wspólników dołączyło do zarządu dwa lata później. Bez dalszych ustaleń w prasie.",note_en:"Pisarek founded the company alone in March 2022 as its sole shareholder and beneficiary; two more shareholders joined the board two years later. No further findings in the press.",sources:'rejestr.io, KRS 0000962034'},
14:{owner:"Adam Krzysztof Sadowski (zarząd) · Dariusz Grabowski (wspólnik)",owner_en:"Adam Krzysztof Sadowski (board) · Dariusz Grabowski (shareholder)",chain:"Sp. z o.o. (PL), założona październik 2024, należy do właścicieli Green House Development (deweloper)",chain_en:"Limited-liability company (PL), founded October 2024, belongs to the owners of Green House Development (a property developer)",benef:"Polska",benef_en:"Poland",note:"Ten sam wzorzec co przy kilku innych operatorach w zbiorze: deweloper nieruchomości prowadzący najem krótkoterminowy jako dodatkową działalność. Spółka aktywnie się rozwija, według prasy branżowej została niedawno wybrana na wyłącznego operatora nowej inwestycji dewelopera TPPI (NanoApart).",note_en:"The same pattern seen at several other operators in this dataset: a property developer running short-term rental as a side business. The company is actively expanding, according to industry press it was recently named exclusive operator of developer TPPI's new project (NanoApart).",sources:'<a href="https://rejestr.io/krs/1135785/solarento" target="_blank" rel="noopener">rejestr.io</a> · <a href="https://inwestycjewkurortach.pl/aktualnosci,operator-wynajmu-apartamentow-solareno-warszawa-nanoapart" target="_blank" rel="noopener">inwestycjewkurortach.pl</a>'},
15:{owner:"Filip Kołowca (jednoosobowa działalność gospodarcza)",owner_en:"Filip Kołowca (sole proprietorship)",chain:"JDG (NIP 6182143380), zarejestrowana w Kaliszu, zarządza ofertami w Warszawie zdalnie",chain_en:"Sole proprietorship (NIP 6182143380), registered in Kalisz, manages Warsaw listings remotely",benef:"Polska",benef_en:"Poland",note:"Kolejny przypadek w zbiorze, gdzie zarejestrowana siedziba działalności leży poza Warszawą, mimo że wszystkie zarządzane oferty są warszawskie. Jak przy innych JDG w tym zbiorze, brak osobnego rejestru beneficjentów do sprawdzenia.",note_en:"Another case in this dataset where the registered business address sits outside Warsaw even though every managed listing is in Warsaw. As with other sole proprietorships in this dataset, there's no separate beneficial-owner register to check.",sources:'dane własne zbioru (business_details, warsaw_listings_enriched.json)'},
16:{owner:"Łukasz Czerwionka (jedyny wspólnik, prezes, beneficjent)",owner_en:"Łukasz Czerwionka (sole shareholder, president, beneficiary)",chain:"Sp. z o.o. (PL), zarejestrowana 25.05.2026",chain_en:"Limited-liability company (PL), registered 25.05.2026",benef:"Polska",benef_en:"Poland",note:"Najmłodsza spółka w rankingu TOP20, zarejestrowana niecałe trzy miesiące przed publikacją tego artykułu, z jednym właścicielem i bez powiązań z innymi podmiotami w rejestrze.",note_en:"The youngest company in the TOP20 ranking, registered less than three months before this article was published, with a single owner and no ties to other entities in the register.",sources:'rejestr.io, KRS 0001243361'},
17:{owner:"Monika Janina Tkacz (prezeska, wspólniczka, beneficjentka od grudnia 2024)",owner_en:"Monika Janina Tkacz (president, shareholder, beneficiary since December 2024)",chain:"Sp. z o.o. (PL), założona lipiec 2022",chain_en:"Limited-liability company (PL), founded July 2022",benef:"Polska",benef_en:"Poland",note:"Tkacz jest jednocześnie powiązana z 9 organizacjami w rejestrze, w tym dwiema podobnie nazwanymi spółkami (Webster Uno, Webster Tres), wzorzec seryjnej działaczki korporacyjnej. Wcześniejszy skład zarządu spółki (przed grudniem 2024) nie był dalej sprawdzany.",note_en:"Tkacz is simultaneously tied to 9 organizations in the register, including two other similarly-named companies (Webster Uno, Webster Tres), a pattern of a serial corporate office-holder. The company's earlier board composition (before December 2024) was not further investigated.",sources:'rejestr.io, KRS 0000977681'},
19:{owner:"Iwona Kopeć i Gérard Bonvicini (założyciele, po 50%) → 90% sprzedane Luisowi Quinie (Portugalia)",owner_en:"Iwona Kopeć and Gérard Bonvicini (founders, 50% each) → 90% sold to Luis Quina (Portugal)",chain:"Sp. z o.o. (PL, KRS 0001150881), założona I 2025 jako Loft Affair Warsaw, przemianowana na Stay Lab; Quina dał Kopeć i Bonviciniemu pełnomocnictwa do reprezentowania go na zgromadzeniach wspólników",chain_en:"Limited-liability company (PL, KRS 0001150881), founded Jan 2025 as Loft Affair Warsaw, renamed Stay Lab; Quina granted Kopeć and Bonvicini power of attorney to represent him at shareholder meetings",benef:"Portugalia (formalnie) · Polska (faktyczna kontrola przez pełnomocnictwo)",benef_en:"Portugal (formally) · Poland (actual control via proxy)",note:"Ta sama para prowadziła też siostrzaną, większą spółkę „Loft Affair”/„LA Group” (ok. 500 mieszkań, przychody 89,6 mln zł w 2024), która 30.01.2026 złożyła wniosek o upadłość w Sądzie Rejonowym w Krakowie z długami szacowanymi na dziesiątki milionów złotych. Bonvicini sprzedał tam swoje 49,5% Kopeć za cenę nominalną, wyceniając całą spółkę na 100 000 zł. Niemal równolegle ta sama para sprzedała 90% Loft Affair Warsaw portugalskiemu inwestorowi i zmieniła jej nazwę na Stay Lab. Zapytani o tożsamość Quiny, właściciele odpowiedzieli tylko ogólnikowo.",note_en:"The same pair also ran a larger, related company, \"Loft Affair\"/\"LA Group\" (about 500 apartments, PLN 89.6 million in revenue in 2024), which filed for bankruptcy in Kraków District Court on 30 Jan 2026 with debts estimated in the tens of millions of złoty. Bonvicini sold his 49.5% stake there to Kopeć for a nominal price, valuing the whole company at PLN 100,000. Almost simultaneously, the same pair sold 90% of Loft Affair Warsaw to a Portuguese investor and renamed it Stay Lab. Asked about Quina's identity, the owners gave only vague answers.",sources:'<a href="https://www.e-hotelarz.pl/artykul/116883/loft-affair-zlozyl-wniosek-o-upadlosc-zmienil-nazwe-i-wlasciciela/" target="_blank" rel="noopener">e-hotelarz.pl</a> · <a href="https://krs-pobierz.pl/stay-lab-spolka-z-ograniczona-odpowiedzialnoscia-i0001150881" target="_blank" rel="noopener">krs-pobierz.pl, KRS 0001150881</a> · <a href="https://www.airbnb.com/rooms/1075314329328345840" target="_blank" rel="noopener">airbnb.com</a>'}};
